<script setup>
import { computed, reactive } from 'vue'
import GraphSequence from './GraphSequence.vue'
import { copyFor } from './copy.js'
import { graphSequence, nodeById } from './model.js'
import { paymentTotal } from '../scenarios/payment-document.js'
const props=defineProps({instance:Object,locale:String,people:Array,actor:Object,busy:Boolean,preview:Boolean,uncertain:Object})
const emit=defineEmits(['decide','retry'])
const t=computed(()=>copyFor(props.locale)), comments=reactive({})
const sequence=computed(()=>{try{return graphSequence(props.instance.definition)}catch{return []}})
const name=id=>props.people?.find(p=>p.id===id)?.displayName||id
const node=id=>nodeById(props.instance.definition,id)
const canVote=task=>!props.preview&&task.status==='ACTIVE'&&task.participants.includes(props.actor?.id)&&!task.votes.some(v=>v.actorId===props.actor.id)
const status=value=>t.value[{PENDING:'pending',APPROVED:'approved',REJECTED:'rejected',ACTIVE:'active',COMPLETED:'completed',CANCELLED:'cancelled',APPROVE:'approved',REJECT:'rejected'}[value]]||value
const factList=computed(()=>props.instance.routes.flatMap(route=>route.evaluations.flatMap(e=>e.facts||[])).filter((f,i,list)=>list.findIndex(x=>x.field===f.field&&x.actualValue===f.actualValue)===i))
</script>
<template>
  <section class="gf-runtime" data-testid="graph-runtime" :data-request-id="instance.id" :data-command-revision="instance.commandRevision" :data-request-status="instance.status" :data-definition-version="instance.definition.version"><header class="gf-runtime-heading"><div><span class="gf-eyebrow">{{ preview?t.previewResult:t.requestDetails }}</span><h2>{{ instance.business.title }}</h2><p>{{ t.frozen }} · v{{ instance.definition.version }} <span class="gf-muted">· {{ t.commandRevision }} {{ instance.commandRevision }}</span></p></div><span class="gf-status" :class="instance.status.toLowerCase()">{{ status(instance.status) }}</span></header>
    <div class="gf-runtime-facts"><div><span>{{ t.netTotal }}</span><strong>{{ instance.business.currency }} {{ paymentTotal(instance.business) }}</strong></div><div><span>{{ t.businessId }}</span><strong>{{ instance.business.businessId }}</strong></div><div><span>{{ t.activeTasks }}</span><strong data-testid="graph-active-count">{{ instance.tasks.filter(task=>task.status==='ACTIVE').length }}</strong></div></div>
    <section v-if="factList.length" class="gf-server-facts"><h3>{{ t.serverFact }}</h3><p v-for="fact in factList" :key="`${fact.field}:${fact.actualValue}`" data-testid="graph-server-fact">{{ t.field }} · {{ t.actual }}: <strong>{{ fact.actualValue }}</strong></p></section>
    <section class="gf-tasks" :aria-label="t.activeTasks"><article v-for="task in instance.tasks" :key="task.id" class="gf-task" :data-task-id="task.id" :data-task-status="task.status" :data-vote-count="task.votes.length" :class="task.status.toLowerCase()" :data-testid="`graph-task-${task.nodeId}`"><header><div><small>{{ t.task }} · {{ task.completionMode }}<span v-if="canVote(task)"> · {{ t.currentUser }}</span></small><h3>{{ node(task.nodeId)?.name || task.nodeId }}</h3></div><span>{{ status(task.status) }}</span></header><p>{{ task.participants.map(name).join(' · ') }}</p><ul v-if="task.votes.length" class="gf-votes" :aria-label="t.taskVotes"><li v-for="vote in task.votes" :key="vote.actorId">{{ name(vote.actorId) }} · {{ status(vote.decision) }}<span v-if="vote.comment"> · {{ vote.comment }}</span></li></ul><template v-if="canVote(task)"><template v-if="uncertain?.[task.id]"><p class="gf-callout">{{ t.decisionUncertain }}</p><button type="button" class="primary" :disabled="busy" :data-testid="`graph-retry-${task.nodeId}`" @click="emit('retry',task)">{{ t.retryDecision }}</button></template><template v-else><label>{{ t.comment }} <small>({{ t.optional }})</small><input v-model="comments[task.id]" :disabled="busy" maxlength="2000" :data-testid="`graph-comment-${task.nodeId}`"></label><div class="gf-button-row"><button type="button" class="gf-danger" :disabled="busy" :data-testid="`graph-reject-${task.nodeId}`" @click="emit('decide',{task,decision:'REJECT',comment:comments[task.id]||''})">{{ t.reject }}</button><button type="button" class="primary" :disabled="busy" :data-testid="`graph-approve-${task.nodeId}`" @click="emit('decide',{task,decision:'APPROVE',comment:comments[task.id]||''})">{{ t.approve }}</button></div></template></template><p v-else-if="task.status==='ACTIVE'&&!preview" class="gf-muted">{{ t.needsOthers }}</p></article><p v-if="!instance.tasks.length">{{ t.noActiveTasks }}</p></section>
    <div v-for="fork in instance.forks" :key="fork.id" class="gf-join-status" :data-fork-id="fork.id" :data-fork-fired="String(fork.fired)" :data-arrived-branch-ids="JSON.stringify(fork.arrivedBranchIds)" :data-expected-branch-ids="JSON.stringify(fork.expectedBranchIds)" :class="{fired:fork.fired}" :data-testid="`graph-join-${fork.joinId}`"><span aria-hidden="true">⊕</span><div><strong>{{ node(fork.joinId)?.name }} · {{ fork.fired?t.joined:instance.status==='REJECTED'?t.cancelled:t.waiting }}</strong><p>{{ fork.arrivedBranchIds.length }} / {{ fork.expectedBranchIds.length }} {{ t.arrived }}<span v-if="instance.status==='REJECTED'&&!fork.fired"> · {{ t.cancelled }}</span></p><ul><li v-for="id in fork.expectedBranchIds" :key="id">{{ instance.definition.edges.find(e=>e.id===id)?.label || id }} · {{ fork.arrivedBranchIds.includes(id)?t.completed:instance.status==='REJECTED'?t.cancelled:t.waitingState }}</li></ul></div></div>
    <div v-for="route in instance.routes" :key="route.gatewayId" class="gf-route-status"><strong>{{ node(route.gatewayId)?.name }} · {{ t.route }}</strong><p>{{ instance.definition.edges.find(e=>e.id===route.selectedEdgeId)?.label || route.selectedEdgeId }}</p><ol><li v-for="evaluation in route.evaluations" :key="evaluation.edgeId">{{ instance.definition.edges.find(e=>e.id===evaluation.edgeId)?.label || evaluation.edgeId }} · {{ evaluation.edgeId===route.selectedEdgeId?t.selected:t.skipped }} · {{ t.evaluated }}: {{ evaluation.result?'true':'false' }}</li></ol></div>
    <div class="gf-canvas gf-runtime-canvas" :aria-label="t.frozen"><GraphSequence :items="sequence" :locale="locale" :people="people" :instance="instance" :editable="false" /></div>
    <details class="gf-activity"><summary>{{ t.activity }} ({{ instance.events.length }})</summary><ol><li v-for="event in instance.events" :key="event.sequence"><strong>#{{ event.sequence }} {{ event.type }}</strong><span>{{ node(event.nodeId)?.name }} · {{ event.detail }}</span><small>{{ new Date(event.at).toLocaleString(locale==='zh'?'zh-CN':'en-GB') }}</small></li></ol></details><details class="gf-json"><summary>{{ t.snapshot }}</summary><pre>{{ JSON.stringify({definition:instance.definition,business:instance.business,routes:instance.routes},null,2) }}</pre></details>
  </section>
</template>
